// Extract params from POST body or query string
const body = $json.body || {};
const query = $json.query || {};

const callSid = body.CallSid || body.callSid || query.callSid || '';
const callerPhone = body.From || body.callerPhone || query.callerPhone || '';
const calledNumber = body.To || body.calledNumber || query.calledNumber || '';

// FIX: Capture SpeechResult so the no-slots retry loop
// passes the caller's NEW utterance to GPT context
const speechResult = body.SpeechResult || query.SpeechResult || '';

if (!callSid) {
  return [{ json: { error: 'No callSid provided', callSid, callerPhone, calledNumber, speechResult } }];
}

return [{ json: { callSid, callerPhone, calledNumber, speechResult } }];

// Build context for GPT to extract booking details
const params = $('Extract Params').first().json;
const sessionData = $('Load Session').first()?.json || {};
const settings = $('Load Account Settings').first()?.json || {};

let history = [];
try {
  history = typeof sessionData.conversation_history === 'string'
    ? JSON.parse(sessionData.conversation_history)
    : (sessionData.conversation_history || []);
} catch(e) { history = []; }

const recentHistory = history.slice(-10)
  .map(m => m.role.toUpperCase() + ': ' + m.content)
  .join('\n');

// FIX: Append caller's new speech so GPT sees the latest request
let fullContext = recentHistory;
if (params.speechResult && params.speechResult.trim()) {
  fullContext += '\nCALLER: ' + params.speechResult.trim();
}

const now = new Date();
const tz = settings.timezone || 'America/Chicago';
const today = now.toLocaleDateString('en-CA', { timeZone: tz });
const dayOfWeek = now.toLocaleDateString('en-US', { timeZone: tz, weekday: 'long' });

const selectedVoice = settings.selected_voice || 'Polly.Matthew-Neural';
const isPolly = selectedVoice.startsWith('Polly.');
const calendarId = settings.google_calendar_id || 'primary';
const duration = settings.booking_duration_minutes || 60;
const buffer = settings.booking_buffer_minutes || 15;

return [{
  json: {
    callSid: params.callSid,
    callerPhone: params.callerPhone,
    calledNumber: params.calledNumber,
    recentHistory: fullContext,
    today,
    dayOfWeek,
    selectedVoice,
    isPolly,
    calendarId,
    duration,
    buffer,
    timezone: tz
  }
}];

// Parse GPT response and resolve time ranges for Free/Busy query
const upstream = $('Prepare Booking Context').first().json;
let raw = $json?.choices?.[0]?.message?.content || $json?.message?.content || '{}';

raw = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let details;
try {
  details = JSON.parse(raw);
} catch(e) {
  details = {};
  const dateMatch = raw.match(/(\d{4}-\d{2}-\d{2})/);
  if (dateMatch) details.date = dateMatch[1];

  const timeMatch = raw.match(/(\d{1,2}:\d{2}\s*(?:AM|PM|am|pm)?)/);
  if (timeMatch) {
    details.time_preference = timeMatch[1].trim();
  }

  if (!details.time_preference) {
    const lower = raw.toLowerCase();
    if (lower.includes('morning')) details.time_preference = 'morning';
    else if (lower.includes('afternoon')) details.time_preference = 'afternoon';
    else if (lower.includes('evening')) details.time_preference = 'evening';
  }
  details.service_type = 'general';
  details.notes = '';
}

const date = details.date || upstream.today;
let timePref = details.time_preference || 'afternoon';
const duration = upstream.duration || 60;
const buffer = upstream.buffer || 15;
const tz = upstream.timezone || 'America/Chicago';

// FIX: Normalize any time value to 24-hour format
function to24h(t) {
  if (!t || typeof t !== 'string') return t;
  t = t.trim();
  if (/^(morning|afternoon|evening)$/i.test(t)) return t.toLowerCase();

  const ampmMatch = t.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM|am|pm)$/);
  if (ampmMatch) {
    let h = parseInt(ampmMatch[1]);
    const m = parseInt(ampmMatch[2] || '0');
    const period = ampmMatch[3].toUpperCase();
    if (period === 'PM' && h < 12) h += 12;
    if (period === 'AM' && h === 12) h = 0;
    return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
  }

  const bareHourMatch = t.match(/^(\d{1,2})$/);
  if (bareHourMatch) {
    let h = parseInt(bareHourMatch[1]);
    if (h >= 1 && h <= 7) h += 12;
    return String(h).padStart(2, '0') + ':00';
  }

  const plainMatch = t.match(/^(\d{1,2}):(\d{2})$/);
  if (plainMatch) {
    let h = parseInt(plainMatch[1]);
    const m = parseInt(plainMatch[2]);
    if (h >= 1 && h <= 7) h += 12;
    return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
  }
  return t;
}

timePref = to24h(timePref);

let startHour, endHour;
if (/^\d{1,2}:\d{2}$/.test(timePref) || /^\d{1,2}$/.test(timePref)) {
  const hour = parseInt(timePref.split(':')[0]);
  startHour = Math.max(8, hour - 2);
  endHour = Math.min(20, hour + 2);
} else if (timePref === 'morning') {
  startHour = 8; endHour = 12;
} else if (timePref === 'afternoon') {
  startHour = 12; endHour = 17;
} else if (timePref === 'evening') {
  startHour = 17; endHour = 20;
} else {
  startHour = 9; endHour = 17;
}

const timeMin = date + 'T' + String(startHour).padStart(2,'0') + ':00:00';
const timeMax = date + 'T' + String(endHour).padStart(2,'0') + ':00:00';

return [{ json: {
  ...upstream,
  bookingDate: date,
  timePref,
  serviceType: details.service_type || 'general',
  bookingNotes: details.notes || '',
  startHour,
  endHour,
  timeMin,
  timeMax,
  parseError: false
}}];

// Build available slots from Google Calendar events response
const upstream = $('Parse Booking Details').first().json;

// Native Google Calendar getAll returns an array of event items
// Each item has: start.dateTime, end.dateTime, summary, etc.
// We need to convert these into busy periods
const calendarId = upstream.calendarId || 'primary';
const date = upstream.bookingDate;
const duration = upstream.duration || 60;
const buffer = upstream.buffer || 15;
const startHour = upstream.startHour;
const endHour = upstream.endHour;
const tz = upstream.timezone || 'America/Chicago';
const timePref = upstream.timePref || '';

// Build busy periods from calendar events
let busyPeriods = [];
try {
  // $input.all() gets all items from the previous node
  const events = $input.all().map(item => item.json);
  busyPeriods = events
    .filter(e => e.start && (e.start.dateTime || e.start.date))
    .map(e => ({
      start: new Date(e.start.dateTime || e.start.date).getTime(),
      end: new Date(e.end.dateTime || e.end.date).getTime()
    }));
} catch(e) {
  busyPeriods = [];
}

// Generate candidate slots in the time range
const slotDuration = duration * 60 * 1000;
const slotBuffer = buffer * 60 * 1000;
const step = 30 * 60 * 1000;

const slots = [];
const rangeStart = new Date(date + 'T' + String(startHour).padStart(2,'0') + ':00:00Z').getTime();
const rangeEnd = new Date(date + 'T' + String(endHour).padStart(2,'0') + ':00:00Z').getTime();

for (let t = rangeStart; t + slotDuration <= rangeEnd; t += step) {
  const slotEnd = t + slotDuration;

  const isBusy = busyPeriods.some(bp => {
    const bpStart = bp.start - slotBuffer;
    const bpEnd = bp.end + slotBuffer;
    return (t < bpEnd && slotEnd > bpStart);
  });

  if (!isBusy) {
    const startDate = new Date(t);
    const endDate = new Date(slotEnd);

    let hours = startDate.getUTCHours();
    let minutes = startDate.getUTCMinutes();
    const ampm = hours >= 12 ? 'PM' : 'AM';
    const displayHour = hours > 12 ? hours - 12 : (hours === 0 ? 12 : hours);
    const displayMin = minutes > 0 ? ':' + String(minutes).padStart(2,'0') : '';
    const label = displayHour + displayMin + ' ' + ampm;

    slots.push({
      start: startDate.toISOString(),
      end: endDate.toISOString(),
      label: label,
      startHour: hours,
      startMinute: minutes
    });
  }
}

// Check if the caller's exact requested time matches an available slot
let exactMatch = null;

if (/^\d{1,2}:\d{2}$/.test(timePref)) {
  const prefHour = parseInt(timePref.split(':')[0]);
  const prefMin = parseInt(timePref.split(':')[1]);

  for (let i = 0; i < slots.length; i++) {
    if (slots[i].startHour === prefHour && slots[i].startMinute === prefMin) {
      exactMatch = slots[i];
      break;
    }
  }

  if (!exactMatch) {
    for (let i = 0; i < slots.length; i++) {
      if (slots[i].startHour === prefHour && Math.abs(slots[i].startMinute - prefMin) <= 30) {
        exactMatch = slots[i];
        break;
      }
    }
  }
}

let selectedSlots;
let isExactMatch = false;

if (exactMatch) {
  selectedSlots = [exactMatch];
  isExactMatch = true;
} else {
  selectedSlots = slots;
  if (slots.length > 4) {
    const interval = Math.floor(slots.length / 4);
    selectedSlots = [slots[0], slots[interval], slots[interval*2], slots[slots.length-1]];
  }
}

let spokenSlots = '';
if (selectedSlots.length === 0) {
  spokenSlots = '';
} else if (selectedSlots.length === 1) {
  spokenSlots = selectedSlots[0].label;
} else {
  const labels = selectedSlots.map(s => s.label);
  spokenSlots = labels.slice(0, -1).join(', ') + ', and ' + labels[labels.length - 1];
}

const dateObj = new Date(date + 'T12:00:00Z');
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const spokenDate = dayNames[dateObj.getUTCDay()] + ' ' + monthNames[dateObj.getUTCMonth()] + ' ' + dateObj.getUTCDate();

return [{ json: {
  ...upstream,
  slots: selectedSlots,
  slotCount: selectedSlots.length,
  spokenSlots,
  spokenDate,
  hasSlots: selectedSlots.length > 0,
  isExactMatch,
  calendarError: false
}}];

// Build TwiML to present available slots or confirm exact match
const d = $json;
const voice = d.selectedVoice || 'Polly.Matthew-Neural';
const isPolly = voice.startsWith('Polly.');
const count = d.slotCount;

let message;
if (d.isExactMatch && count === 1) {
  // Caller's exact requested time is available — ask yes/no
  message = d.spokenDate + ' at ' + d.spokenSlots + ' is available. Shall I book that for you?';
} else if (count === 1) {
  // Only one slot open, but not an exact match
  message = 'The closest available time on ' + d.spokenDate + ' is ' + d.spokenSlots + '. Would that work for you?';
} else {
  // Multiple slots — list them
  message = 'I have ' + count + ' openings on ' + d.spokenDate + ': ' + d.spokenSlots + '. Which time works best for you?';
}

const confirmUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/appointment-confirm';

const fallbackMsg = "I didn't catch your preference. Let me take note of your preferred time and someone will confirm by text.";
const returnUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=1';

let twiml;
if (isPolly) {
  twiml = '<Response>' +
    '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + confirmUrl + '" method="POST">' +
      '<Say voice="' + voice + '">' + message + '</Say>' +
    '</Gather>' +
    '<Say voice="' + voice + '">' + fallbackMsg + '</Say>' +
    '<Redirect method="POST">' + returnUrl + '</Redirect>' +
  '</Response>';
} else {
  const audioUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/get-growth-audio?text=' + encodeURIComponent(message) + '&amp;voice_id=' + voice;
  const fallbackAudioUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/get-growth-audio?text=' + encodeURIComponent(fallbackMsg) + '&amp;voice_id=' + voice;
  twiml = '<Response>' +
    '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + confirmUrl + '" method="POST">' +
      '<Play>' + audioUrl + '</Play>' +
    '</Gather>' +
    '<Play>' + fallbackAudioUrl + '</Play>' +
    '<Redirect method="POST">' + returnUrl + '</Redirect>' +
  '</Response>';
}

// Save booking context for confirmation step
const bookingContext = JSON.stringify({
  state: d.isExactMatch ? 'awaiting_confirmation' : 'awaiting_selection',
  date: d.bookingDate,
  spokenDate: d.spokenDate,
  slots: d.slots,
  isExactMatch: d.isExactMatch || false,
  serviceType: d.serviceType,
  notes: d.bookingNotes
}).replace(/'/g, "''");

return [{ json: { twiml, bookingContext, callSid: d.callSid } }];

// No availability — offer alternatives
const d = $('Build Available Slots').first().json;
const voice = d.selectedVoice || 'Polly.Matthew-Neural';
const isPolly = voice.startsWith('Polly.');

const message = "I'm sorry, " + d.spokenDate + " is fully booked in that time range. Would you like to try a different day or time?";

const retryUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/appointment-booking';
const returnUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=1';
const gatherUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=0';

let twiml;
if (isPolly) {
  twiml = '<Response>' +
    '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + retryUrl + '" method="POST">' +
      '<Say voice="' + voice + '">' + message + '</Say>' +
    '</Gather>' +
    '<Redirect method="POST">' + returnUrl + '</Redirect>' +
  '</Response>';
} else {
  const audioUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/get-growth-audio?text=' + encodeURIComponent(message) + '&amp;voice_id=' + voice;
  twiml = '<Response>' +
    '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + retryUrl + '" method="POST">' +
      '<Play>' + audioUrl + '</Play>' +
    '</Gather>' +
    '<Redirect method="POST">' + returnUrl + '</Redirect>' +
  '</Response>';
}

// Also prepare history update
const callSid = d.callSid || '';
const historyMsg = message.replace(/'/g, "''").substring(0, 500);
const historyUpdateSql = "UPDATE voice_sessions SET conversation_history = (SELECT jsonb_agg(elem) FROM (SELECT elem FROM jsonb_array_elements(conversation_history) AS elem UNION ALL SELECT '{\"role\": \"assistant\", \"content\": \"" + historyMsg + "\", \"timestamp\": \"" + new Date().toISOString() + "\"}'::jsonb) sub) WHERE call_sid = '" + callSid + "';";

return [{ json: { twiml, historyUpdateSql, callSid } }];

// Parse error or calendar failure — fall back to manual capture
const params = $('Extract Params').first().json;
const settings = $('Load Account Settings').first()?.json || {};
const voice = settings.selected_voice || 'Polly.Matthew-Neural';
const isPolly = voice.startsWith('Polly.');

const message = "I'm having a little trouble checking the calendar right now. Let me take note of your preferred time, and someone from our team will confirm your appointment by text shortly.";
const returnUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=1';
const gatherUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=0';

let twiml;
if (isPolly) {
  twiml = '<Response>' +
    '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + gatherUrl + '" method="POST">' +
      '<Say voice="' + voice + '">' + message + '</Say>' +
    '</Gather>' +
    '<Redirect method="POST">' + returnUrl + '</Redirect>' +
  '</Response>';
} else {
  const audioUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/get-growth-audio?text=' + encodeURIComponent(message) + '&amp;voice_id=' + voice;
  twiml = '<Response>' +
    '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + gatherUrl + '" method="POST">' +
      '<Play>' + audioUrl + '</Play>' +
    '</Gather>' +
    '<Redirect method="POST">' + returnUrl + '</Redirect>' +
  '</Response>';
}

// Also prepare history update
const callSid = params.callSid || '';
const historyMsg = message.replace(/'/g, "''").substring(0, 500);
const historyUpdateSql = "UPDATE voice_sessions SET conversation_history = (SELECT jsonb_agg(elem) FROM (SELECT elem FROM jsonb_array_elements(conversation_history) AS elem UNION ALL SELECT '{\"role\": \"assistant\", \"content\": \"" + historyMsg + "\", \"timestamp\": \"" + new Date().toISOString() + "\"}'::jsonb) sub) WHERE call_sid = '" + callSid + "';";

return [{ json: { twiml, historyUpdateSql, callSid } }];

// Extract speech result and params
const body = $json.body || {};
const query = $json.query || {};

return [{ json: {
  speechResult: body.SpeechResult || '',
  callSid: body.CallSid || query.callSid || '',
  callerPhone: body.From || query.callerPhone || '',
  calledNumber: body.To || query.calledNumber || ''
}}];

// Parse booking context and match caller's slot selection
const params = $('Extract Confirm Params').first().json;
const contextRow = $('Load Booking Context').first()?.json || {};
const settings = $('Load Settings 2').first()?.json || {};

let bookingCtx;
try {
  bookingCtx = typeof contextRow.booking_context === 'string'
    ? JSON.parse(contextRow.booking_context)
    : (contextRow.booking_context || {});
} catch(e) {
  bookingCtx = {};
}

const slots = bookingCtx.slots || [];
const speech = (params.speechResult || '').toLowerCase().trim();
const voice = settings.selected_voice || 'Polly.Matthew-Neural';
const isPolly = voice.startsWith('Polly.');
const calendarId = settings.google_calendar_id || 'primary';
const duration = settings.booking_duration_minutes || 60;
const isExactMatch = bookingCtx.isExactMatch || false;

// Helper: word boundary match
function wordMatch(haystack, needle) {
  const re = new RegExp('\\b' + needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b');
  return re.test(haystack);
}

// Normalize speech: "12:00 p.m." → "12:00 pm", "3 a. m." → "3 am"
const normalizedSpeech = speech
  .replace(/p\.\s*m\.?/gi, 'pm')
  .replace(/a\.\s*m\.?/gi, 'am')
  .replace(/\s+/g, ' ')
  .trim();

let matchedSlot = null;
let matchIndex = -1;

// === EXACT MATCH PATH: caller was asked yes/no about one specific slot ===
if (isExactMatch && slots.length === 1) {
  const affirmatives = ['yes', 'yeah', 'sure', 'that works', 'perfect', 'okay', 'ok',
    'sounds good', 'yep', 'absolutely', 'please', 'book it', 'go ahead',
    "that's fine", 'works for me', "let's do it", 'confirm',
    'make that', 'make it', 'schedule that', 'schedule it', 'set it',
    'do that', 'do it', 'can you make', 'can you book', 'can you schedule',
    'that time', 'that one', 'go for it', 'lock it in', 'sounds perfect',
    'works great', "that's great", "that's perfect", 'i want that'];

  const negatives = ['no', 'nope', 'not that', 'different', 'another', 'other',
    'change', 'something else', 'try again', "don't want", 'not really'];

  if (affirmatives.some(a => normalizedSpeech.includes(a) || speech.includes(a))) {
    matchedSlot = slots[0];
    matchIndex = 0;
  } else if (negatives.some(n => normalizedSpeech.includes(n) || speech.includes(n))) {
    matchedSlot = null;
  }

  // If caller restated the time (e.g. "can you make that March 25th at 12:00 p.m.")
  if (!matchedSlot && !negatives.some(n => speech.includes(n))) {
    const slot = slots[0];
    const h = slot.startHour;
    const m = slot.startMinute || 0;
    const h12 = h > 12 ? h - 12 : (h === 0 ? 12 : h);
    const mStr = String(m).padStart(2, '0');
    const ampm = h >= 12 ? 'pm' : 'am';

    const timePatterns = [
      slot.label.toLowerCase(),
      slot.label.toLowerCase().replace(/\s+/g, ''),
      h12 + ':' + mStr,
      h12 + ':' + mStr + ' ' + ampm,
      h12 + ':' + mStr + ampm,
      String(h12) + ' ' + ampm,
      String(h12) + ampm,
      String(h12),
    ];

    if (timePatterns.some(t => normalizedSpeech.includes(t) || speech.includes(t))) {
      matchedSlot = slots[0];
      matchIndex = 0;
    }
  }
}

// === MULTI-SLOT PATH: caller picks from a list ===
if (!matchedSlot && !isExactMatch) {
  let bestScore = 0;

  for (let i = 0; i < slots.length; i++) {
    const label = slots[i].label.toLowerCase();
    const h = slots[i].startHour;
    const m = slots[i].startMinute || 0;
    const h12 = h > 12 ? h - 12 : (h === 0 ? 12 : h);
    const mStr = String(m).padStart(2, '0');
    let score = 0;

    if (normalizedSpeech.includes(label) || speech.includes(label)) {
      score = 100;
    } else if (normalizedSpeech.includes(label.replace(/\s+/g, ''))) {
      score = 95;
    } else if (normalizedSpeech.includes(h12 + ':' + mStr)) {
      score = 90;
    } else if (wordMatch(normalizedSpeech, label.split(' ')[0])) {
      score = 80;
    } else {
      const colonTime = h + ':' + mStr;
      if (speech.includes(colonTime)) {
        score = 85;
      }
    }

    if (score === 0) {
      const ordinals = [
        ['first', '1st', 'one'],
        ['second', '2nd', 'two'],
        ['third', '3rd', 'three'],
        ['fourth', '4th', 'four']
      ];
      const safeOrdinals = [
        ['first', '1st'],
        ['second', '2nd'],
        ['third', '3rd'],
        ['fourth', '4th']
      ];
      if (i < ordinals.length) {
        if (safeOrdinals[i] && safeOrdinals[i].some(o => speech.includes(o))) {
          score = 70;
        } else if (ordinals[i].some(o => wordMatch(speech, o))) {
          score = 60;
        }
      }
    }

    if (score > bestScore) {
      bestScore = score;
      matchedSlot = slots[i];
      matchIndex = i;
    }
  }

  // Single-slot affirmative (non-exact, e.g. "closest time is 10:30")
  if (!matchedSlot && slots.length === 1) {
    const affirmatives = ['yes', 'yeah', 'sure', 'that works', 'perfect', 'okay', 'ok', 'sounds good', 'yep'];
    if (affirmatives.some(a => speech.includes(a))) {
      matchedSlot = slots[0];
      matchIndex = 0;
    }
  }
}

// === LAST RESORT: caller restated time in exact-match context ===
if (!matchedSlot && isExactMatch) {
  for (let i = 0; i < slots.length; i++) {
    const label = slots[i].label.toLowerCase();
    if (normalizedSpeech.includes(label) || speech.includes(label) ||
        normalizedSpeech.includes(label.replace(/\s+/g, ''))) {
      matchedSlot = slots[i];
      matchIndex = i;
      break;
    }
  }
}

// Check if caller wants to cancel
const cancelPhrases = ['never mind', 'nevermind', 'cancel', 'no thanks', 'forget it', 'go back', 'actually no'];
const isCancel = cancelPhrases.some(pp => speech.includes(pp));

return [{ json: {
  callSid: params.callSid,
  callerPhone: params.callerPhone,
  calledNumber: params.calledNumber,
  speechResult: params.speechResult,
  matchedSlot,
  matchIndex,
  isCancel,
  hasMatch: matchedSlot !== null,
  slots,
  bookingDate: bookingCtx.date,
  spokenDate: bookingCtx.spokenDate,
  serviceType: bookingCtx.serviceType || 'general',
  bookingNotes: bookingCtx.notes || '',
  selectedVoice: voice,
  isPolly,
  calendarId,
  duration
}}];

// Save booking record and build confirmation TwiML
const d = $('Match Slot Selection').first().json;
const eventResponse = $json;
const slot = d.matchedSlot;

const googleEventId = eventResponse?.id || '';
const calendarLink = eventResponse?.htmlLink || '';

// Format confirmation time for speech
const spokenTime = slot.label;
const spokenDate = d.spokenDate;
const confirmMsg = "Perfect, you're booked for " + spokenDate + " at " + spokenTime + ". I've sent a confirmation text to your phone. Is there anything else I can help you with?";

const voice = d.selectedVoice;
const isPolly = d.isPolly;
const returnUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=1';
const gatherUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=0';

let twiml;
if (isPolly) {
  twiml = '<Response>' +
    '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + gatherUrl + '" method="POST">' +
      '<Say voice="' + voice + '">' + confirmMsg + '</Say>' +
    '</Gather>' +
    '<Redirect method="POST">' + returnUrl + '</Redirect>' +
  '</Response>';
} else {
  const audioUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/get-growth-audio?text=' + encodeURIComponent(confirmMsg) + '&amp;voice_id=' + voice;
  twiml = '<Response>' +
    '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + gatherUrl + '" method="POST">' +
      '<Play>' + audioUrl + '</Play>' +
    '</Gather>' +
    '<Redirect method="POST">' + returnUrl + '</Redirect>' +
  '</Response>';
}

// SMS confirmation text
