// Caller didn't clearly pick a slot — ask again or handle cancel
const d = $('Match Slot Selection').first().json;
const voice = d.selectedVoice;
const isPolly = d.isPolly;
const returnUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=1';
const gatherUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=0';

let message, twiml;

if (d.isCancel) {
  // Caller wants to cancel booking
  message = "No problem! Let me know if there's anything else I can help you with.";
  if (isPolly) {
    twiml = '<Response>' +
      '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + gatherUrl + '" method="POST">' +
        '<Say voice="' + voice + '">' + message + '</Say>' +
      '</Gather>' +
      '<Redirect method="POST">' + returnUrl + '</Redirect>' +
    '</Response>';
  } else {
    const audioUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/get-growth-audio?text=' + encodeURIComponent(message) + '&amp;voice_id=' + voice;
    twiml = '<Response>' +
      '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + gatherUrl + '" method="POST">' +
        '<Play>' + audioUrl + '</Play>' +
      '</Gather>' +
      '<Redirect method="POST">' + returnUrl + '</Redirect>' +
    '</Response>';
  }
} else {
  // Unclear — ask again
  const slotLabels = d.slots.map(s => s.label).join(', ');
  message = "I didn't quite catch which time you preferred. The available times are " + slotLabels + ". Which one works for you?";

  const retryUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/appointment-confirm';

  if (isPolly) {
    twiml = '<Response>' +
      '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + retryUrl + '" method="POST">' +
        '<Say voice="' + voice + '">' + message + '</Say>' +
      '</Gather>' +
      '<Redirect method="POST">' + returnUrl + '</Redirect>' +
    '</Response>';
  } else {
    const audioUrl = 'https://chi-360dmmc.app.n8n.cloud/webhook/get-growth-audio?text=' + encodeURIComponent(message) + '&amp;voice_id=' + voice;
    twiml = '<Response>' +
      '<Gather input="speech" language="en-US" speechTimeout="auto" action="' + retryUrl + '" method="POST">' +
        '<Play>' + audioUrl + '</Play>' +
      '</Gather>' +
      '<Redirect method="POST">' + returnUrl + '</Redirect>' +
    '</Response>';
  }
}

// Prepare history update
const callSid = d.callSid || '';
const historyMsg = message.replace(/'/g, "''").substring(0, 500);
const speechMsg = (d.speechResult || '').replace(/'/g, "''").substring(0, 500);
const historyUpdateSql = "UPDATE voice_sessions SET conversation_history = (SELECT jsonb_agg(elem) FROM (SELECT elem FROM jsonb_array_elements(conversation_history) AS elem UNION ALL SELECT '{\"role\": \"user\", \"content\": \"" + speechMsg + "\", \"timestamp\": \"" + new Date().toISOString() + "\"}'::jsonb UNION ALL SELECT '{\"role\": \"assistant\", \"content\": \"" + historyMsg + "\", \"timestamp\": \"" + new Date().toISOString() + "\"}'::jsonb) sub) WHERE call_sid = '" + callSid + "';";

return [{ json: { twiml, historyUpdateSql, callSid } }];
